 {channel:'ZALO',installationId:'QA_OA_A',destinationId:'QA_OA_DEST_A',tenantId:'TENANT_SHARED_QA',storeId:'STORE_A',authUserId:'AUTH_USER_A',senderId:'QA_SENDER_A',sku:'SKU_A',orderId:'ORDER_A',priceVnd:159000},
