];
const cases=[];
let seq=0;
for(const p of profiles){
 const firstEventId='QA_EVT_'+String(seq+1).padStart(4,'0');
 const foreign=p.storeId==='STORE_A'?'STORE_B':'STORE_A';
 const foreignSku=p.storeId==='STORE_A'?'SKU_B':'SKU_A';
 const foreignOrder=p.storeId==='STORE_A'?'ORDER_B':'ORDER_A';
 const foreignSender=p.storeId==='STORE_A'?'QA_SENDER_B':'QA_SENDER_A';
 const foreignAuth=p.storeId==='STORE_A'?'AUTH_USER_B':'AUTH_USER_A';
 function add(name,changed,expected='DENY'){
   const eventId='QA_EVT_'+String(++seq).padStart(4,'0');
   cases.push({caseId:'P_'+String(seq).padStart(4,'0'),
    name,channel:p.channel,installationId:p.installationId,
    destinationId:p.destinationId,tenantIdHint:p.tenantId,
    authUserIdHint:p.authUserId,senderId:p.senderId,
    eventId,occurredAtMs:1794899000000,
    source:'SYNTHETIC_QA_ONLY',authReceipt:'QA_FAKE_AUTH_PROOF',
    providerReceipt:'QA_FAKE_PROVIDER_PROOF',isEcho:false,
    installationActive:true,ownershipActive:true,
    jwtSessionActive:true,atomicReplayAccepted:true,rateAllowed:true,
    action:'READ_PUBLIC_CATALOG',sku:p.sku,orderId:p.orderId,
    accessGrantStoreId:p.storeId,accessGrantSenderId:p.senderId,
    accessGrantValid:true,query:'áo thun size M',
    quantity:1,expectedTotalVnd:p.priceVnd,
    customerConfirmed:true,modelOrigin:'MODEL_PROPOSAL',
    expected, ...changed});
 }
 add('own catalog preview',{},'SIMULATED_CATALOG_READ_PLAN');
 add('own catalog exact SKU',{query:'SKU'},'SIMULATED_CATALOG_READ_PLAN');
 add('own order status scoped',{action:'READ_OWN_ORDER_STATUS'},'SIMULATED_ORDER_STATUS_PLAN');
 add('cross Store catalog',{sku:foreignSku});
 add('cross Store order',{action:'READ_OWN_ORDER_STATUS',orderId:foreignOrder});
 add('wrong customer sender grant',{action:'READ_OWN_ORDER_STATUS',accessGrantSenderId:foreignSender});
 add('foreign customer Store grant',{action:'READ_OWN_ORDER_STATUS',accessGrantStoreId:foreign});
 add('missing order access grant',{action:'READ_OWN_ORDER_STATUS',accessGrantValid:false});
 add('expired auth session',{jwtSessionActive:false});
 add('disabled owner Store binding',{ownershipActive:false});
 add('disabled channel installation',{installationActive:false});
 add('wrong Page OA destination',{destinationId:'FOREIGN_DEST'});
 add('unknown installation ID',{installationId:'FAKE_INSTALLATION'});
 add('spoof tenant ID',{tenantId:'TENANT_FOREIGN'});
 add('spoof store ID',{storeId:foreign});
 add('spoof auth user ID',{authUserId:foreignAuth});
 add('client declares owner',{ownerVerified:true});
 add('client declares admin',{isAdmin:true});
 add('client declares service role',{serviceRole:'service_role'});
 add('client supplies jwt',{jwt:'QA_CLIENT_FAKE_JWT'});
 add('client supplies user metadata',{user_metadata:{storeId:foreign}});
 add('client supplies app metadata',{app_metadata:{role:'super_admin'}});
 add('client supplies order grant',{orderAccessGrant:'QA_FORGED'});
 add('client supplies provider signature flag',{signatureVerified:true});
 add('client supplies credential',{credential:'not_real_credential'});
 add('client supplies modelWriteAllowed',{modelCanWrite:true});
 add('wrong auth server receipt',{authReceipt:'CLIENT_BOOLEAN_VERIFIED'});
 add('wrong provider receipt',{providerReceipt:'CLIENT_BOOLEAN_VERIFIED'});
 add('signed provider proof missing',{providerReceipt:null});
 add('JWT verified by source only',{authReceipt:'REAL_JWT'});
 add('provider proof verified by source only',{providerReceipt:'REAL_PROVIDER'});
 add('signed event stale',{occurredAtMs:1794899000000-300001});
 add('sender self echo',{isEcho:true});
 add('rate limited',{rateAllowed:false});
 add('replay cache denied',{atomicReplayAccepted:false});
 add('duplicate event replay',{eventId:firstEventId});
 add('unauthorized send',{action:'SEND_MESSAGE'});
 add('unauthorized create order',{action:'CREATE_ORDER'});
 add('unauthorized update order',{action:'UPDATE_ORDER'});
 add('unauthorized change price',{action:'UPDATE_PRICE'});
 add('unauthorized change stock',{action:'UPDATE_STOCK'});
 add('unauthorized credential read',{action:'READ_CREDENTIAL'});
 add('arbitrary URL fetch',{action:'FETCH_EXTERNAL_URL'});
 add('image injection provenance',{modelOrigin:'PRODUCT_IMAGE'});
 add('catalog injection provenance',{modelOrigin:'PRODUCT_CATALOG'});
 add('RAG injection provenance',{modelOrigin:'KNOWLEDGE_DOCUMENT'});
 add('invalid query payload',{query:'https://attacker.example'});
 add('invalid excessive query',{query:'x'.repeat(130)});
 add('propose order cannot execute write',{action:'PROPOSE_ORDER'});
 add('customer cross-channel identity without challenge',{action:'READ_CROSS_CHANNEL_ORDER'});
 add('unknown new tool',{action:'PLUGINS_INSTALL'});
 add('forced production admission attempt',{admissionMode:'REAL_PRODUCTION'});
}
return [{json:{contract:'T404_V171P_SAME_TENANT_AUTH_STORE_READER_GATE_QA_V1',
 mode:'INACTIVE_MANUAL_SYNTHETIC_ONLY',syntheticOnly:true,
 sourceCheckpoint:'V17.1O',publishedMessengerVersion:'1064b1b3-d3f1-4a6b-a367-2414ba691522',
 publishedZaloVersion:'2d912cb0-007f-452f-9536-b92ba12a03e6',
 realJwtVerified:false,realProviderOwnerVerified:false,actualReaderAttached:false,
 nowMs:1794899000000,fixturesPerProfile:cases.length/4,total:cases.length,cases}}];

const indata=$input.first()?.json||{};
if(indata.contract!=='T404_V171P_SAME_TENANT_AUTH_STORE_READER_GATE_QA_V1'||
 indata.mode!=='INACTIVE_MANUAL_SYNTHETIC_ONLY'||indata.syntheticOnly!==true||
 !Array.isArray(indata.cases)||indata.total!==indata.cases.length||
 indata.total<150||indata.total>250||
 indata.realJwtVerified!==false||indata.realProviderOwnerVerified!==false||
 indata.actualReaderAttached!==false)throw Error('V171P_INGRESS_NOT_SYNTHETIC_NO_GO');
const reg={
 'MESSENGER:QA_PAGE_A':{destinationId:'QA_PAGE_DEST_A',tenantId:'TENANT_SHARED_QA',storeId:'STORE_A',authUserId:'AUTH_USER_A',senderId:'QA_SENDER_A',sku:'SKU_A',orderId:'ORDER_A'},
 'MESSENGER:QA_PAGE_B':{destinationId:'QA_PAGE_DEST_B',tenantId:'TENANT_SHARED_QA',storeId:'STORE_B',authUserId:'AUTH_USER_B',senderId:'QA_SENDER_B',sku:'SKU_B',orderId:'ORDER_B'},
 'ZALO:QA_OA_A':{destinationId:'QA_OA_DEST_A',tenantId:'TENANT_SHARED_QA',storeId:'STORE_A',authUserId:'AUTH_USER_A',senderId:'QA_SENDER_A',sku:'SKU_A',orderId:'ORDER_A'},
 'ZALO:QA_OA_B':{destinationId:'QA_OA_DEST_B',tenantId:'TENANT_SHARED_QA',storeId:'STORE_B',authUserId:'AUTH_USER_B',senderId:'QA_SENDER_B',sku:'SKU_B',orderId:'ORDER_B'}
};
const forbidden=['tenantId','storeId','authUserId','ownerVerified','isAdmin','serviceRole','jwt','user_metadata','app_metadata','orderAccessGrant','signatureVerified','credential','modelCanWrite','apiKey','targetRecipientId','authorization','privateKey'];
const seen=new Set();
const results=[];
for(const c of indata.cases){
 let reason='DEFAULT_DENY',decision='DENY',scope=reg[c.channel+':'+c.installationId];
 if(!scope||c.destinationId!==scope.destinationId||
   c.source!=='SYNTHETIC_QA_ONLY'||c.admissionMode!==undefined||
   c.authReceipt!=='QA_FAKE_AUTH_PROOF'||
   c.providerReceipt!=='QA_FAKE_PROVIDER_PROOF'||
   c.installationActive!==true||c.ownershipActive!==true||
   c.jwtSessionActive!==true||c.senderId!==scope.senderId||
   c.authUserIdHint!==scope.authUserId||
   c.tenantIdHint!==scope.tenantId||c.isEcho===true)
  reason='FAKE_OR_UNVERIFIED_AUTH_PROVIDER_INSTALLATION';
 else if(forbidden.some(k=>Object.prototype.hasOwnProperty.call(c,k)))
  reason='CLIENT_CLAIMED_PRIVILEGE_OR_STORE';
 else if(!Number.isSafeInteger(c.occurredAtMs)||
    Math.abs(indata.nowMs-c.occurredAtMs)>300000)reason='STALE_EVENT';
 else {
  const key=scope.tenantId+':'+scope.storeId+':'+c.channel+':'+c.installationId+':'+c.eventId;
  if(!/^QA_EVT_[0-9]{4}$/.test(String(c.eventId||''))||seen.has(key)||c.atomicReplayAccepted!==true)reason='REPLAY_OR_NOT_DURABLY_ACCEPTED';
  else {
   seen.add(key);
   if(c.rateAllowed!==true||c.modelOrigin!=='MODEL_PROPOSAL'||
      typeof c.query!=='string'||c.query.length>120||!/[\p{L}\p{N}]/u.test(c.query)||!/^[\p{L}\p{N}_ .-]{1,120}$/u.test(c.query)||
      /https?:\/\/|www\.|(?:password|token|credential|api.?key|secret|otp)/i.test(c.query))
      reason='RATE_OR_UNTRUSTED_TOOL_INPUT';
   else if(c.action==='READ_PUBLIC_CATALOG'){
      if(c.sku===scope.sku){
       decision='SIMULATED_CATALOG_READ_PLAN';reason='QA_CATALOG_PLAN_ONLY';
      }else reason='CROSS_STORE_CATALOG_DENIED';
   }else if(c.action==='READ_OWN_ORDER_STATUS'){
      if(c.orderId===scope.orderId&&
        c.accessGrantValid===true&&
        c.accessGrantStoreId===scope.storeId&&
        c.accessGrantSenderId===scope.senderId){
       decision='SIMULATED_ORDER_STATUS_PLAN';reason='QA_ORDER_GRANT_PLAN_ONLY';
      }else reason='CROSS_STORE_OR_CUSTOMER_ORDER_DENIED';
   }else reason='NOT_IN_SOURCE_ONLY_READ_ALLOWLIST';
  }
 }
 results.push({caseId:c.caseId,scenario:c.name,channel:c.channel,
  expected:c.expected,decision,passed:decision===c.expected,
  reason,tenantId:decision==='DENY'?null:scope?.tenantId,
  storeId:decision==='DENY'?null:scope?.storeId,
  sku:decision==='SIMULATED_CATALOG_READ_PLAN'?scope.sku:null,
  orderId:decision==='SIMULATED_ORDER_STATUS_PLAN'?scope.orderId:null,
  actualCommerceReaderExecuted:false,
  independentRealJwtVerified:false,
  independentRealProviderEventVerified:false,
  actualWrites:0,actualSends:0});
}
return [{json:{contract:indata.contract,mode:'SOURCE_ONLY_ADMISSION_GATE',
 total:results.length,passed:results.filter(x=>x.passed).length,
 denied:results.filter(x=>x.decision==='DENY').length,
 catalogPlans:results.filter(x=>x.decision==='SIMULATED_CATALOG_READ_PLAN').length,
 orderStatusPlans:results.filter(x=>x.decision==='SIMULATED_ORDER_STATUS_PLAN').length,
 results,realJwtAuthorizations:0,realProviderSignedEvents:0,
 actualCommerceReads:0,actualCommerceWrites:0,actualProviderMessagesSent:0,
 hostedRlsVerified:false,hostedJwtStoreAAndBVerified:false,liveReleaseApproved:false}}];

const d=$input.first()?.json||{};
if(d.contract!=='T404_V171P_SAME_TENANT_AUTH_STORE_READER_GATE_QA_V1'||
 d.mode!=='SOURCE_ONLY_ADMISSION_GATE'||!Array.isArray(d.results))throw Error('V171P_UNTRUSTED_READER_PLAN');
const catalog={STORE_A:{sku:'SKU_A',priceVnd:159000},STORE_B:{sku:'SKU_B',priceVnd:189000}};
const orders={STORE_A:{orderId:'ORDER_A',status:'PENDING_FAKE'},STORE_B:{orderId:'ORDER_B',status:'PENDING_FAKE'}};
const previews=[];
for(const p of d.results){
 if(p.decision==='SIMULATED_CATALOG_READ_PLAN'){
  const item=catalog[p.storeId];
  if(!item||p.sku!==item.sku||p.tenantId!=='TENANT_SHARED_QA')throw Error('V171P_CATALOG_PLAN_SCOPE_MISMATCH');
  previews.push({caseId:p.caseId,kind:'CATALOG',
    storeId:p.storeId,sku:item.sku,priceVnd:item.priceVnd,
    dataSource:'SYNTHETIC_CODE_ONLY',canReadHostedDatabase:false});
 }
 if(p.decision==='SIMULATED_ORDER_STATUS_PLAN'){
  const item=orders[p.storeId];
  if(!item||p.orderId!==item.orderId||p.tenantId!=='TENANT_SHARED_QA')throw Error('V171P_ORDER_PLAN_SCOPE_MISMATCH');
  previews.push({caseId:p.caseId,kind:'OWN_ORDER_STATUS',
    storeId:p.storeId,orderId:item.orderId,status:item.status,
    dataSource:'SYNTHETIC_CODE_ONLY',canReadHostedDatabase:false});
 }
}
return [{json:{...d,previews,actualPostgrestRequests:0,
 actualCustomerDataRead:0,realCommerceReaderInvocations:0,
 sourceOnlyModelIdentityProof:false}}];
